import pandas as pd

def find_second_day_signups(emails: pd.DataFrame, texts: pd.DataFrame) -> pd.DataFrame:
    if emails.empty or texts.empty:
        return pd.DataFrame(columns=['user_id'])

    merged = emails.merge(texts, on='email_id')
    merged['signup_date'] = pd.to_datetime(merged['signup_date']).dt.date
    merged['action_date'] = pd.to_datetime(merged['action_date']).dt.date

    cond = (merged['signup_action'] == 'Verified') & ((merged['action_date'] - merged['signup_date']).dt.days == 1)
    res = merged[cond][['user_id']].drop_duplicates().sort_values(by='user_id').reset_index(drop=True)
    return res
